BOOK.add({
  subject: "math",
  id: "math-01",
  title: "दाशमिक प्रणाली — मीट्रिक प्रणाली, लंबाई, क्षेत्रफल, आयतन, द्रव्यमान, समय के माप",
  notes: "\n<h3>1. दाशमिक (मीट्रिक) प्रणाली क्या है?</h3>\n<p>जिस माप-प्रणाली में हर बड़ी इकाई अपनी छोटी इकाई की <b>10 गुनी</b> होती है, उसे <b>दाशमिक या मीट्रिक प्रणाली</b> कहते हैं। इसकी शुरुआत <b>फ्रांस</b> में (फ्रांसीसी क्रांति के बाद, 1790 के दशक में) हुई। 1960 में इसी पर आधारित <b>अंतर्राष्ट्रीय मात्रक प्रणाली (SI)</b> अपनाई गई। भारत में मानक बाट और माप अधिनियम, 1956 के बाद मीट्रिक प्रणाली चरणबद्ध रूप से लागू हुई और दाशमिक सिक्का प्रणाली (1 रुपया = 100 नए पैसे) 1 अप्रैल 1957 से लागू हुई।</p>\n<ul>\n<li>लंबाई की मूल इकाई — <b>मीटर (m)</b></li>\n<li>द्रव्यमान की मूल इकाई — <b>ग्राम (g)</b> (SI में मूल इकाई <b>किलोग्राम</b>)</li>\n<li>धारिता (तरल का आयतन) की मूल इकाई — <b>लीटर (L)</b></li>\n<li>समय की SI इकाई — <b>सेकंड (s)</b> (समय दाशमिक नहीं है: 60 सेकंड = 1 मिनट)</li>\n</ul>\n\n<h3>2. उपसर्ग (Prefix) — पूरी प्रणाली की कुंजी</h3>\n<table>\n<tr><th>उपसर्ग</th><th>संकेत</th><th>गुणक</th><th>उदाहरण</th></tr>\n<tr><td>किलो</td><td>k</td><td>1000 (10<sup>3</sup>)</td><td>1 किमी = 1000 मी</td></tr>\n<tr><td>हेक्टो</td><td>h</td><td>100 (10<sup>2</sup>)</td><td>1 हेक्टोमीटर = 100 मी</td></tr>\n<tr><td>डेका</td><td>da</td><td>10</td><td>1 डेकामीटर = 10 मी</td></tr>\n<tr><td>(मूल इकाई)</td><td>—</td><td>1</td><td>मीटर / ग्राम / लीटर</td></tr>\n<tr><td>डेसी</td><td>d</td><td>1/10 (10<sup>-1</sup>)</td><td>1 डेसीमीटर = 0.1 मी</td></tr>\n<tr><td>सेंटी</td><td>c</td><td>1/100 (10<sup>-2</sup>)</td><td>1 सेमी = 0.01 मी</td></tr>\n<tr><td>मिली</td><td>m</td><td>1/1000 (10<sup>-3</sup>)</td><td>1 मिमी = 0.001 मी</td></tr>\n<tr><td>माइक्रो</td><td>μ</td><td>10<sup>-6</sup></td><td>1 माइक्रोमीटर</td></tr>\n<tr><td>नैनो</td><td>n</td><td>10<sup>-9</sup></td><td>1 नैनोमीटर</td></tr>\n<tr><td>मेगा / गीगा</td><td>M / G</td><td>10<sup>6</sup> / 10<sup>9</sup></td><td>मेगावाट, गीगाबाइट</td></tr>\n</table>\n<div class=\"tip\">क्रम याद रखने की ट्रिक: <b>\"कि-हे-डे-मू-डे-से-मि\"</b> (किलो, हेक्टो, डेका, मूल, डेसी, सेंटी, मिली)। बाएँ से दाएँ (बड़ी से छोटी) जाने पर हर कदम पर <b>×10</b>, दाएँ से बाएँ जाने पर हर कदम पर <b>÷10</b>।</div>\n\n<h3>3. लंबाई के माप</h3>\n<table>\n<tr><th>इकाई</th><th>मान</th></tr>\n<tr><td>10 मिलीमीटर</td><td>1 सेंटीमीटर</td></tr>\n<tr><td>10 सेंटीमीटर</td><td>1 डेसीमीटर</td></tr>\n<tr><td>10 डेसीमीटर (100 सेमी)</td><td>1 मीटर</td></tr>\n<tr><td>10 मीटर</td><td>1 डेकामीटर</td></tr>\n<tr><td>10 डेकामीटर (100 मी)</td><td>1 हेक्टोमीटर</td></tr>\n<tr><td>10 हेक्टोमीटर (1000 मी)</td><td>1 किलोमीटर</td></tr>\n</table>\n<p><b>ब्रिटिश (FPS) इकाइयाँ व रूपांतरण:</b> 12 इंच = 1 फुट; 3 फुट = 1 गज; 1760 गज = 1 मील = 5280 फुट।<br>\n1 इंच = 2.54 सेमी (परिभाषित, ठीक); 1 फुट = 30.48 सेमी; 1 गज = 0.9144 मी; 1 मीटर ≈ 39.37 इंच; 1 मील ≈ 1.609 किमी; 1 किमी ≈ 0.621 मील; 1 समुद्री (नॉटिकल) मील = 1852 मी।</p>\n<p><b>अति छोटी/बड़ी दूरियाँ:</b> 1 माइक्रोन (माइक्रोमीटर) = 10<sup>-6</sup> मी; 1 नैनोमीटर = 10<sup>-9</sup> मी; 1 एंगस्ट्रॉम (Å) = 10<sup>-10</sup> मी; 1 प्रकाश वर्ष ≈ 9.46 × 10<sup>15</sup> मी (यह <b>दूरी</b> का मात्रक है, समय का नहीं); 1 खगोलीय इकाई (AU) ≈ 1.496 × 10<sup>11</sup> मी (पृथ्वी-सूर्य की औसत दूरी)।</p>\n\n<h3>4. क्षेत्रफल के माप</h3>\n<p><b>मुख्य नियम:</b> लंबाई की इकाई 10 गुनी हो तो क्षेत्रफल की इकाई <b>10² = 100 गुनी</b> होती है।</p>\n<table>\n<tr><th>इकाई</th><th>मान</th></tr>\n<tr><td>1 वर्ग सेमी</td><td>100 वर्ग मिमी</td></tr>\n<tr><td>1 वर्ग मीटर</td><td>10,000 वर्ग सेमी</td></tr>\n<tr><td>1 एयर (are) = 1 वर्ग डेकामीटर</td><td>100 वर्ग मीटर</td></tr>\n<tr><td>1 <b>हेक्टेयर</b> = 1 वर्ग हेक्टोमीटर</td><td>100 एयर = <b>10,000 वर्ग मीटर</b></td></tr>\n<tr><td>1 वर्ग किलोमीटर</td><td>100 हेक्टेयर = 10,00,000 वर्ग मीटर</td></tr>\n</table>\n<p><b>भूमि की इकाइयाँ (छत्तीसगढ़ में प्रचलित):</b> 1 एकड़ = 4840 वर्ग गज = 43,560 वर्ग फुट ≈ <b>4047 वर्ग मीटर</b> ≈ 0.4047 हेक्टेयर। 1 हेक्टेयर ≈ <b>2.47 एकड़</b>। 1 एकड़ = 100 डिसमिल (1 डिसमिल = 435.6 वर्ग फुट)। 1 वर्ग गज = 9 वर्ग फुट; 1 वर्ग फुट = 144 वर्ग इंच।</p>\n<div class=\"tip\">भूमि-अभिलेख (पटवारी/तहसील) में रकबा प्रायः हेक्टेयर में लिखा जाता है। एकड़ → हेक्टेयर: × 0.4047 (लगभग ÷ 2.47); हेक्टेयर → एकड़: × 2.47।</div>\n\n<h3>5. आयतन व धारिता के माप</h3>\n<p><b>मुख्य नियम:</b> लंबाई की इकाई 10 गुनी हो तो आयतन की इकाई <b>10³ = 1000 गुनी</b> होती है।</p>\n<table>\n<tr><th>संबंध</th><th>मान</th></tr>\n<tr><td>1 घन सेमी (cc)</td><td>1000 घन मिमी = <b>1 मिलीलीटर</b></td></tr>\n<tr><td>1 घन डेसीमीटर</td><td>1000 घन सेमी = <b>1 लीटर</b></td></tr>\n<tr><td>1 घन मीटर</td><td>10,00,000 घन सेमी = <b>1000 लीटर</b> = 1 किलोलीटर</td></tr>\n<tr><td>1 लीटर</td><td>10 डेसीलीटर = 100 सेंटीलीटर = 1000 मिलीलीटर</td></tr>\n</table>\n<p><b>पानी का विशेष संबंध (4°C पर):</b> 1 मिली पानी ≈ 1 ग्राम; 1 लीटर पानी ≈ 1 किग्रा; 1 घन मीटर पानी ≈ 1000 किग्रा = 1 टन। टंकी के प्रश्नों में यही प्रयोग होता है।</p>\n\n<h3>6. द्रव्यमान (भार) के माप</h3>\n<table>\n<tr><th>इकाई</th><th>मान</th></tr>\n<tr><td>10 मिलीग्राम</td><td>1 सेंटीग्राम</td></tr>\n<tr><td>10 सेंटीग्राम</td><td>1 डेसीग्राम</td></tr>\n<tr><td>10 डेसीग्राम</td><td>1 ग्राम</td></tr>\n<tr><td>1000 ग्राम</td><td>1 किलोग्राम</td></tr>\n<tr><td>100 किलोग्राम</td><td>1 <b>क्विंटल</b></td></tr>\n<tr><td>10 क्विंटल = 1000 किग्रा</td><td>1 <b>मीट्रिक टन</b></td></tr>\n</table>\n<p>1 किग्रा ≈ 2.2 पाउंड; 1 पाउंड ≈ 453.6 ग्राम; 1 कैरेट (रत्न) = 200 मिलीग्राम। धान खरीदी (समर्थन मूल्य) <b>प्रति क्विंटल</b> घोषित होती है — इसलिए क्विंटल-किग्रा रूपांतरण के प्रश्न सामान्य हैं।</p>\n\n<h3>7. समय के माप (दाशमिक नहीं)</h3>\n<table>\n<tr><th>इकाई</th><th>मान</th></tr>\n<tr><td>1 मिनट</td><td>60 सेकंड</td></tr>\n<tr><td>1 घंटा</td><td>60 मिनट = 3600 सेकंड</td></tr>\n<tr><td>1 दिन</td><td>24 घंटे = 1440 मिनट = 86,400 सेकंड</td></tr>\n<tr><td>1 सप्ताह</td><td>7 दिन = 168 घंटे</td></tr>\n<tr><td>1 साधारण वर्ष</td><td>365 दिन = 52 सप्ताह + 1 दिन = 8760 घंटे</td></tr>\n<tr><td>1 लीप वर्ष</td><td>366 दिन = 52 सप्ताह + 2 दिन</td></tr>\n<tr><td>दशक / शताब्दी / सहस्राब्दी</td><td>10 / 100 / 1000 वर्ष</td></tr>\n</table>\n<p><b>लीप वर्ष नियम:</b> जो वर्ष 4 से विभाज्य हो वह लीप वर्ष; परंतु शताब्दी वर्ष (00 वाला) तभी लीप वर्ष जब 400 से विभाज्य हो। जैसे 2000 लीप वर्ष था, 1900 नहीं।</p>\n<p><b>महीनों के दिन:</b> 31 दिन — जनवरी, मार्च, मई, जुलाई, अगस्त, अक्टूबर, दिसंबर; 30 दिन — अप्रैल, जून, सितंबर, नवंबर; फरवरी — 28 (लीप में 29)।</p>\n<p><b>12 घंटे से 24 घंटे घड़ी:</b> दोपहर 1 बजे के बाद के PM समय में 12 जोड़ें (3:40 PM = 15:40)। रात 12 बजे = 00:00; दोपहर 12 बजे = 12:00।</p>\n<p><b>घड़ी की सुइयाँ:</b> मिनट की सुई 1 मिनट में 6° और घंटे की सुई 1 मिनट में 0.5° घूमती है। 1 घंटे में मिनट की सुई 360°, घंटे की सुई 30°।</p>\n\n<h3>8. ताप के माप (सम्बद्ध)</h3>\n<p>C/5 = (F − 32)/9 = (K − 273)/5। −40° पर सेल्सियस और फ़ारेनहाइट दोनों समान। शरीर का सामान्य ताप 37°C = 98.6°F। पानी का क्वथनांक 100°C = 212°F = 373 K।</p>\n\n<h3>9. रूपांतरण की विधि (हल सहित उदाहरण)</h3>\n<p><b>उदाहरण 1:</b> 7 किमी 45 मी को मीटर में लिखें।<br>हल: 7 × 1000 + 45 = <b>7045 मी</b>। (ध्यान: 45 मी को किमी में लिखें तो 0.045 किमी, अतः 7.045 किमी — 7.45 नहीं!)</p>\n<p><b>उदाहरण 2:</b> 2.5 हेक्टेयर को वर्ग मीटर में बदलें।<br>हल: 2.5 × 10,000 = <b>25,000 वर्ग मी</b>।</p>\n<p><b>उदाहरण 3:</b> एक टंकी 2 मी × 1.5 मी × 1.2 मी है। इसमें कितने लीटर पानी आएगा?<br>हल: आयतन = 3.6 घन मी = 3.6 × 1000 = <b>3600 लीटर</b>।</p>\n<p><b>उदाहरण 4:</b> 3.6 क्विंटल चावल को 400 ग्राम के कितने पैकेटों में भरा जा सकता है?<br>हल: 3.6 क्विंटल = 360 किग्रा = 3,60,000 ग्राम; 3,60,000 ÷ 400 = <b>900 पैकेट</b>।</p>\n<p><b>उदाहरण 5:</b> 4 घंटे 25 मिनट 30 सेकंड को सेकंड में बदलें।<br>हल: 4 × 3600 + 25 × 60 + 30 = 14400 + 1500 + 30 = <b>15,930 सेकंड</b>।</p>\n<p><b>उदाहरण 6:</b> एक खेत 500 मी लंबा व 300 मी चौड़ा है। क्षेत्रफल हेक्टेयर व एकड़ में?<br>हल: 1,50,000 वर्ग मी = <b>15 हेक्टेयर</b> ≈ 15 × 2.47 ≈ <b>37 एकड़</b>।</p>\n<p><b>उदाहरण 7:</b> 1 जनवरी से 31 मार्च 2024 तक (दोनों दिन सहित) कितने दिन?<br>हल: 2024 लीप वर्ष है: 31 + 29 + 31 = <b>91 दिन</b>।</p>\n<div class=\"tip\">परीक्षा में सबसे सामान्य गलती: क्षेत्रफल/आयतन बदलते समय केवल 10 या 100 से गुणा कर देना। सदैव याद रखें — लंबाई ×10, क्षेत्रफल ×100, आयतन ×1000 (प्रति एक उपसर्ग-कदम)।</div>\n",
  extra: "\n<h3>शॉर्टकट व गहन ट्रिक्स</h3>\n<h4>1. दशमलव खिसकाने की विधि</h4>\n<ul>\n<li>बड़ी इकाई → छोटी इकाई: जितने कदम नीचे, उतने स्थान दशमलव <b>दाएँ</b> (लंबाई में 1 कदम = 1 स्थान, क्षेत्रफल में 2 स्थान, आयतन में 3 स्थान)।</li>\n<li>उदाहरण: 3.7 किमी → मी: किमी से मी तक 3 कदम, अतः 3700 मी। 0.6 हेक्टेयर (वर्ग हेक्टोमीटर) → वर्ग मी: 2 कदम × 2 = 4 स्थान, अतः 6000 वर्ग मी।</li>\n<li>5 घन मी → घन सेमी: 2 कदम (मी→डेसी→सेंटी) × 3 = 6 स्थान, अतः 50,00,000 घन सेमी।</li>\n</ul>\n<h4>2. याद रखने योग्य \"जादुई\" संख्याएँ</h4>\n<table>\n<tr><th>संबंध</th><th>मान</th><th>स्मृति संकेत</th></tr>\n<tr><td>1 एकड़</td><td>≈ 4047 वर्ग मी ≈ 0.4 हेक्टेयर</td><td>\"40-47\"</td></tr>\n<tr><td>1 हेक्टेयर</td><td>≈ 2.47 एकड़</td><td>2.5 एकड़ से थोड़ा कम</td></tr>\n<tr><td>1 मील</td><td>≈ 1.6 किमी</td><td>5 मील ≈ 8 किमी</td></tr>\n<tr><td>1 किग्रा</td><td>≈ 2.2 पाउंड</td><td>—</td></tr>\n<tr><td>1 इंच</td><td>= 2.54 सेमी</td><td>फुट = 30.48 सेमी</td></tr>\n<tr><td>1 दिन</td><td>= 86,400 सेकंड</td><td>24 × 3600</td></tr>\n</table>\n<h4>3. समय के प्रश्नों की ट्रिक</h4>\n<ul>\n<li>घंटे को दशमलव में बदलना: 0.1 घंटा = 6 मिनट; 0.25 घंटा = 15 मिनट; 0.75 घंटा = 45 मिनट; 0.4 घंटा = 24 मिनट।</li>\n<li>मिनट को घंटे में: 10 मिनट = 1/6 घंटा, 12 मिनट = 1/5 घंटा, 20 मिनट = 1/3 घंटा, 40 मिनट = 2/3 घंटा, 45 मिनट = 3/4 घंटा।</li>\n<li>दिनों की गिनती में \"दोनों दिन सहित\" हो तो अंतर में +1 करें; \"पहला दिन छोड़कर\" हो तो केवल अंतर।</li>\n<li>विषम दिन: साधारण वर्ष = 1, लीप वर्ष = 2, 100 वर्ष = 5, 200 वर्ष = 3, 300 वर्ष = 1, 400 वर्ष = 0 (कैलेंडर के प्रश्नों का आधार)।</li>\n</ul>\n<h4>4. इकाई-जाँच (Unit check) से उत्तर छाँटना</h4>\n<ul>\n<li>टंकी का आयतन घन सेमी में मिला हो तो ÷ 1000 = लीटर; घन मी में मिला हो तो × 1000 = लीटर।</li>\n<li>भाग देने के प्रश्न (पैकेट, टुकड़े, बोतलें) में पहले दोनों राशियों को <b>एक ही इकाई</b> में लाएँ, फिर भाग दें।</li>\n<li>\"मिश्र इकाई\" (जैसे 5 किग्रा 75 ग्राम) को दशमलव में लिखते समय छोटी इकाई के अंक-स्थान पूरे भरें: 75 ग्राम = 0.075 किग्रा, 5 ग्राम = 0.005 किग्रा।</li>\n</ul>\n<h4>5. बारीक तथ्य</h4>\n<ul>\n<li>SI की 7 मूल इकाइयाँ: मीटर, किलोग्राम, सेकंड, एम्पियर, केल्विन, मोल, कैंडेला। \"ग्राम\" मूल SI इकाई नहीं है, किलोग्राम है।</li>\n<li>लीटर SI इकाई नहीं है, पर SI के साथ प्रयोग के लिए स्वीकृत है; आयतन की SI इकाई घन मीटर है।</li>\n<li>हेक्टेयर भी SI के साथ स्वीकृत इकाई है; \"हेक्टेयर\" = हेक्टो + एयर।</li>\n<li>टन तीन प्रकार के होते हैं — मीट्रिक टन (1000 किग्रा), लंबा/ब्रिटिश टन (≈1016 किग्रा), छोटा/अमेरिकी टन (≈907 किग्रा)। परीक्षा में \"टन\" का अर्थ मीट्रिक टन ही लें।</li>\n<li>घड़ी में प्रतिदिन सुइयाँ 22 बार एक-दूसरे पर आती हैं, 22 बार समकोण बनाती हैं (44 बार 90° पर) — घड़ी-अध्याय का आधार।</li>\n</ul>\n",
  questions: [
    {"q":"1 किलोमीटर में कितने मीटर होते हैं?","o":["10","100","1000","10000"],"a":2,"e":"<b>हल:</b><br>चरण 1: उपसर्ग \"किलो\" का अर्थ है 1000 गुना।<br>चरण 2: 1 किलोमीटर = 1000 × 1 मीटर = 1000 मीटर।<br>अतः उत्तर = <b>1000 मीटर</b><br><b>ध्यान दें:</b> किलो = 1000, हेक्टो = 100, डेका = 10 — 100 (हेक्टो) से भ्रमित न हों।"},
    {"q":"1 हेक्टेयर बराबर होता है —","o":["1000 वर्ग मीटर","10,000 वर्ग मीटर","1,00,000 वर्ग मीटर","100 वर्ग मीटर"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 हेक्टेयर = 100 मी भुजा वाले वर्ग का क्षेत्रफल।<br>चरण 2: क्षेत्रफल = 100 मी × 100 मी = 10,000 वर्ग मी।<br>अतः उत्तर = <b>10,000 वर्ग मीटर</b><br><b>शॉर्टकट:</b> 1 एयर (are) = 100 वर्ग मी; 1 हेक्टेयर = 100 एयर = 10,000 वर्ग मी।<br><b>ध्यान दें:</b> 1000 वर्ग मी गलत है — हेक्टो (100) का वर्ग लेना है: 100² = 10,000।"},
    {"q":"1 लीटर = ? घन सेंटीमीटर","o":["10","100","10000","1000"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 लीटर = 1 घन डेसीमीटर, और 1 डेसीमीटर = 10 सेमी।<br>चरण 2: 1 घन डेसीमीटर = 10 × 10 × 10 घन सेमी = 1000 घन सेमी।<br>अतः उत्तर = <b>1000</b><br><b>शॉर्टकट:</b> 1 मिलीलीटर = 1 घन सेमी, अतः 1 लीटर = 1000 मिली = 1000 घन सेमी।"},
    {"q":"1 क्विंटल में कितने किलोग्राम होते हैं?","o":["100","1000","10","50"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 क्विंटल = 100 किलोग्राम (परिभाषा)।<br>चरण 2: इसी प्रकार 10 क्विंटल = 1000 किग्रा = 1 टन।<br>अतः उत्तर = <b>100</b><br><b>ध्यान दें:</b> 1000 किग्रा = 1 टन होता है, क्विंटल नहीं।"},
    {"q":"1 मीट्रिक टन = ? क्विंटल","o":["100","10","1000","20"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 मीट्रिक टन = 1000 किग्रा और 1 क्विंटल = 100 किग्रा।<br>चरण 2: क्विंटल की संख्या = 1000 ÷ 100 = 10।<br>अतः उत्तर = <b>10 क्विंटल</b>"},
    {"q":"5 किमी 25 मी को मीटर में लिखें।","o":["5250 मी","525 मी","5025 मी","50250 मी"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 किमी = 1000 मी, अतः 5 किमी = 5 × 1000 = 5000 मी।<br>चरण 2: कुल = 5000 + 25 = 5025 मी।<br>अतः उत्तर = <b>5025 मी</b><br><b>शॉर्टकट:</b> 5.025 किमी — दशमलव के बाद तीन अंक (025) मीटर बताते हैं।<br><b>ध्यान दें:</b> 5250 मी वह गलती है जब 25 को 250 मान लिया जाए; दशमलव के बाद तीन स्थान भरने हैं।"},
    {"q":"1 वर्ग किलोमीटर में कितने हेक्टेयर होते हैं?","o":["10","1000","10000","100"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 वर्ग किमी = 1000 मी × 1000 मी = 10,00,000 वर्ग मी।<br>चरण 2: 1 हेक्टेयर = 10,000 वर्ग मी।<br>चरण 3: हेक्टेयर = 10,00,000 ÷ 10,000 = 100।<br>अतः उत्तर = <b>100 हेक्टेयर</b>"},
    {"q":"1 घन मीटर में कितने लीटर होते हैं?","o":["1000","100","10000","10"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 घन मी = 100 × 100 × 100 = 10,00,000 घन सेमी।<br>चरण 2: 1 लीटर = 1000 घन सेमी।<br>चरण 3: लीटर = 10,00,000 ÷ 1000 = 1000।<br>अतः उत्तर = <b>1000 लीटर</b><br><b>शॉर्टकट:</b> 1 घन मी = 1000 लीटर = 1 किलोलीटर (पानी के लिए लगभग 1 टन)।"},
    {"q":"1 एकड़ लगभग कितने वर्ग मीटर के बराबर है?","o":["4840","4047","2471","10000"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 एकड़ = 4840 वर्ग गज और 1 गज = 0.9144 मी।<br>चरण 2: 1 वर्ग गज = 0.9144² ≈ 0.8361 वर्ग मी।<br>चरण 3: 4840 × 0.8361 ≈ 4046.86 ≈ 4047 वर्ग मी।<br>अतः उत्तर = <b>4047 वर्ग मीटर</b><br><b>शॉर्टकट:</b> 1 हेक्टेयर ≈ 2.47 एकड़ ⇒ 1 एकड़ ≈ 10,000 ÷ 2.47 ≈ 4047 वर्ग मी।<br><b>ध्यान दें:</b> 4840 वर्ग गज में है, वर्ग मीटर में नहीं; 2471 तो 1000 हेक्टेयर ≈ 2471 एकड़ से आता भ्रम है।"},
    {"q":"1 हेक्टेयर लगभग कितने एकड़ के बराबर है?","o":["0.405","4.84","2.47","1.5"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 हेक्टेयर = 10,000 वर्ग मी, 1 एकड़ ≈ 4047 वर्ग मी।<br>चरण 2: एकड़ = 10,000 ÷ 4047 ≈ 2.47।<br>अतः उत्तर = <b>2.47 एकड़</b><br><b>ध्यान दें:</b> 0.405 उल्टा मान है (1 एकड़ ≈ 0.405 हेक्टेयर)।"},
    {"q":"1 एकड़ = ? वर्ग गज","o":["4047","5280","1760","4840"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 एकड़ = 4840 वर्ग गज (मानक परिभाषा)।<br>चरण 2: चूँकि 1 वर्ग गज = 9 वर्ग फुट, अतः 1 एकड़ = 4840 × 9 = 43,560 वर्ग फुट।<br>अतः उत्तर = <b>4840</b><br><b>ध्यान दें:</b> 4047 वर्ग मीटर का मान है; 1760 गज = 1 मील; 5280 फुट = 1 मील।"},
    {"q":"1 मील लगभग कितने किलोमीटर के बराबर है?","o":["1.609","1.5","1.852","0.621"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 मील = 1760 गज = 1760 × 0.9144 मी।<br>चरण 2: = 1609.34 मी ≈ 1.609 किमी।<br>अतः उत्तर = <b>1.609</b><br><b>ध्यान दें:</b> 1.852 किमी समुद्री मील (nautical mile) है; 0.621 उल्टा मान (1 किमी ≈ 0.621 मील) है।"},
    {"q":"1 इंच = ? सेंटीमीटर","o":["2.45","2.54","3.48","1.54"],"a":1,"e":"<b>हल:</b><br>चरण 1: अंतरराष्ट्रीय परिभाषा से 1 इंच = ठीक 2.54 सेमी।<br>अतः उत्तर = <b>2.54</b><br><b>ध्यान दें:</b> 2.45 अंकों के उलट-फेर की गलती है।"},
    {"q":"1 किलोग्राम लगभग कितने पाउंड के बराबर है?","o":["0.45","2.54","2.2","1.6"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 पाउंड = 0.4536 किग्रा।<br>चरण 2: 1 किग्रा = 1 ÷ 0.4536 ≈ 2.2046 ≈ 2.2 पाउंड।<br>अतः उत्तर = <b>2.2</b><br><b>ध्यान दें:</b> 0.45 उल्टा मान (1 पाउंड ≈ 0.45 किग्रा) है; 2.54 इंच–सेमी का मान है।"},
    {"q":"2.5 लीटर = ? मिलीलीटर","o":["250","25000","2.5","2500"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 लीटर = 1000 मिलीलीटर।<br>चरण 2: 2.5 लीटर = 2.5 × 1000 = 2500 मिली।<br>अतः उत्तर = <b>2500</b><br><b>शॉर्टकट:</b> बड़ी इकाई से छोटी में जाने पर गुणा करें — दशमलव तीन स्थान दाईं ओर खिसकाएँ।"},
    {"q":"एक दिन में कितने सेकंड होते हैं?","o":["86400","3600","8640","864000"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 दिन = 24 घंटे, 1 घंटा = 60 मिनट, 1 मिनट = 60 सेकंड।<br>चरण 2: सेकंड = 24 × 60 × 60 = 24 × 3600 = 86,400।<br>अतः उत्तर = <b>86400</b><br><b>ध्यान दें:</b> 3600 केवल 1 घंटे के सेकंड हैं।"},
    {"q":"एक सप्ताह में कितने घंटे होते हैं?","o":["148","168","186","160"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 सप्ताह = 7 दिन, 1 दिन = 24 घंटे।<br>चरण 2: घंटे = 7 × 24 = 168।<br>अतः उत्तर = <b>168 घंटे</b>"},
    {"q":"एक साधारण (अलीप) वर्ष में कितने सप्ताह होते हैं?","o":["52 सप्ताह","52 सप्ताह 2 दिन","52 सप्ताह 1 दिन","53 सप्ताह"],"a":2,"e":"<b>हल:</b><br>चरण 1: साधारण वर्ष = 365 दिन।<br>चरण 2: 365 ÷ 7 = 52 शेष 1, अर्थात 365 = 52 × 7 + 1।<br>अतः उत्तर = <b>52 सप्ताह 1 दिन</b><br><b>ध्यान दें:</b> लीप वर्ष (366 दिन) में 52 सप्ताह 2 दिन होते हैं — दोनों को न मिलाएँ।"},
    {"q":"एक लीप वर्ष में कितने विषम दिन होते हैं?","o":["0","1","3","2"],"a":3,"e":"<b>हल:</b><br>चरण 1: लीप वर्ष = 366 दिन।<br>चरण 2: 366 ÷ 7 = 52 शेष 2।<br>चरण 3: सप्ताह पूरे होने के बाद बचे दिन ही विषम दिन होते हैं = 2।<br>अतः उत्तर = <b>2</b><br><b>ध्यान दें:</b> साधारण वर्ष में 1 विषम दिन होता है।"},
    {"q":"दोपहर बाद 2:45 बजे (2:45 PM) को 24 घंटे की घड़ी में कैसे लिखेंगे?","o":["14:45","02:45","12:45","16:45"],"a":0,"e":"<b>हल:</b><br>चरण 1: 24 घंटे की घड़ी में दोपहर 1 बजे से रात 11:59 तक के PM समय में 12 जोड़ते हैं।<br>चरण 2: 2 + 12 = 14, मिनट वही रहेंगे → 14:45।<br>अतः उत्तर = <b>14:45</b><br><b>ध्यान दें:</b> 02:45 तो रात 2:45 (AM) होगा।"},
    {"q":"3 घंटे 20 मिनट = ? सेकंड","o":["1200","12000","10200","12200"],"a":1,"e":"<b>हल:</b><br>चरण 1: 3 घंटे = 3 × 60 = 180 मिनट; कुल = 180 + 20 = 200 मिनट।<br>चरण 2: सेकंड = 200 × 60 = 12,000।<br>अतः उत्तर = <b>12000</b><br><b>शॉर्टकट:</b> सीधे: 3 × 3600 + 20 × 60 = 10800 + 1200 = 12000।<br><b>ध्यान दें:</b> 10200 वह गलती है जहाँ 20 मिनट को 20 × 60 के बजाय कम जोड़ा गया।"},
    {"q":"0.75 घंटा = ? मिनट","o":["75","40","45","35"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 घंटा = 60 मिनट।<br>चरण 2: 0.75 घंटा = 0.75 × 60 = 45 मिनट।<br>अतः उत्तर = <b>45 मिनट</b><br><b>शॉर्टकट:</b> 0.75 = 3/4, और 60 का 3/4 = 45।<br><b>ध्यान दें:</b> 0.75 घंटे को 75 मिनट न समझें — घंटा 100 मिनट का नहीं होता।"},
    {"q":"एक आयताकार खेत 400 मी लंबा और 250 मी चौड़ा है। इसका क्षेत्रफल कितने हेक्टेयर है?","o":["1","100","40","10"],"a":3,"e":"<b>हल:</b><br>चरण 1: क्षेत्रफल = लंबाई × चौड़ाई = 400 × 250 = 1,00,000 वर्ग मी।<br>चरण 2: 1 हेक्टेयर = 10,000 वर्ग मी।<br>चरण 3: हेक्टेयर = 1,00,000 ÷ 10,000 = 10।<br>अतः उत्तर = <b>10 हेक्टेयर</b>"},
    {"q":"1 वर्ग मीटर = ? वर्ग सेंटीमीटर","o":["10,000","100","1,000","1,00,000"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 मी = 100 सेमी।<br>चरण 2: 1 वर्ग मी = 100 सेमी × 100 सेमी = 10,000 वर्ग सेमी।<br>अतः उत्तर = <b>10,000</b><br><b>शॉर्टकट:</b> क्षेत्रफल में रूपांतरण गुणक का वर्ग लगता है: 100² = 10,000।<br><b>ध्यान दें:</b> 100 केवल लंबाई का गुणक है, क्षेत्रफल का नहीं।"},
    {"q":"1 घन मीटर = ? घन सेंटीमीटर","o":["10,000","10,00,000","1,00,000","1,000"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 मी = 100 सेमी।<br>चरण 2: 1 घन मी = 100 × 100 × 100 = 10,00,000 घन सेमी।<br>अतः उत्तर = <b>10,00,000</b><br><b>शॉर्टकट:</b> आयतन में गुणक का घन लगता है: 100³ = 10⁶।"},
    {"q":"एक टंकी 2 मी लंबी, 1.5 मी चौड़ी और 1 मी गहरी है। इसकी धारिता कितनी है?","o":["300 लीटर","30000 लीटर","3000 लीटर","30 लीटर"],"a":2,"e":"<b>हल:</b><br>चरण 1: आयतन = लंबाई × चौड़ाई × गहराई = 2 × 1.5 × 1 = 3 घन मी।<br>चरण 2: 1 घन मी = 1000 लीटर।<br>चरण 3: धारिता = 3 × 1000 = 3000 लीटर।<br>अतः उत्तर = <b>3000 लीटर</b><br><b>ध्यान दें:</b> 30000 लीटर तब आता है जब 1 घन मी = 10,000 लीटर मान लिया जाए — यह गलत है।"},
    {"q":"1 डेकामीटर = ? मीटर","o":["100","0.1","1000","10"],"a":3,"e":"<b>हल:</b><br>चरण 1: उपसर्ग \"डेका\" का अर्थ है 10 गुना।<br>चरण 2: 1 डेकामीटर = 10 मीटर।<br>अतः उत्तर = <b>10</b><br><b>शॉर्टकट:</b> क्रम याद रखें: किलो(1000) → हेक्टो(100) → डेका(10) → मूल इकाई → डेसी(1/10) → सेंटी(1/100) → मिली(1/1000)।<br><b>ध्यान दें:</b> 0.1 डेसी का मान है, डेका का नहीं।"},
    {"q":"1 हेक्टोमीटर = ? मीटर","o":["100","10","1000","0.01"],"a":0,"e":"<b>हल:</b><br>चरण 1: उपसर्ग \"हेक्टो\" = 100 गुना।<br>चरण 2: 1 हेक्टोमीटर = 100 मीटर।<br>अतः उत्तर = <b>100</b>"},
    {"q":"1 डेसीमीटर = ? सेंटीमीटर","o":["100","10","0.1","1"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 डेसीमीटर = 1/10 मी = 100/10 सेमी।<br>चरण 2: = 10 सेमी।<br>अतः उत्तर = <b>10</b><br><b>ध्यान दें:</b> डेसी और सेंटी दोनों मीटर के भाग हैं; उनके बीच अनुपात 10 का है।"},
    {"q":"मीट्रिक उपसर्ग \"मिली\" का अर्थ है —","o":["1/10","1/100","1/1000","1000"],"a":2,"e":"<b>हल:</b><br>चरण 1: \"मिली\" का अर्थ है हज़ारवाँ भाग।<br>चरण 2: जैसे 1 मिलीमीटर = 1/1000 मीटर।<br>अतः उत्तर = <b>1/1000</b><br><b>ध्यान दें:</b> 1/100 = सेंटी, 1/10 = डेसी।"},
    {"q":"उपसर्ग \"माइक्रो\" का मान है —","o":["10<sup>-3</sup>","10<sup>-9</sup>","10<sup>6</sup>","10<sup>-6</sup>"],"a":3,"e":"<b>हल:</b><br>चरण 1: मीट्रिक उपसर्गों का क्रम: मिली = 10⁻³, माइक्रो = 10⁻⁶, नैनो = 10⁻⁹।<br>चरण 2: अतः माइक्रो = 10⁻⁶ (दस लाखवाँ भाग)।<br>अतः उत्तर = <b>10⁻⁶</b><br><b>शॉर्टकट:</b> छोटे उपसर्ग 3-3 की घात से घटते हैं: मिली(−3), माइक्रो(−6), नैनो(−9), पिको(−12)।<br><b>ध्यान दें:</b> 10⁶ मेगा का मान है।"},
    {"q":"1 नैनोमीटर = ? मीटर","o":["10<sup>-9</sup>","10<sup>-6</sup>","10<sup>-10</sup>","10<sup>-12</sup>"],"a":0,"e":"<b>हल:</b><br>चरण 1: \"नैनो\" = 10⁻⁹।<br>चरण 2: 1 नैनोमीटर = 10⁻⁹ मीटर।<br>अतः उत्तर = <b>10⁻⁹ मी</b><br><b>ध्यान दें:</b> 10⁻¹⁰ मी एंगस्ट्रॉम है; 10⁻⁶ मी माइक्रोमीटर है।"},
    {"q":"1 एंगस्ट्रॉम (Å) बराबर है —","o":["10<sup>-8</sup> मी","10<sup>-10</sup> मी","10<sup>-9</sup> मी","10<sup>-12</sup> मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 एंगस्ट्रॉम = 10⁻¹⁰ मीटर (परमाणु आकार मापने की इकाई)।<br>चरण 2: अर्थात 1 nm = 10 Å।<br>अतः उत्तर = <b>10⁻¹⁰ मी</b><br><b>ध्यान दें:</b> 10⁻⁹ मी नैनोमीटर है — इससे भ्रमित न हों।"},
    {"q":"3.5 टन = ? किलोग्राम","o":["350","35000","3500","35"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 टन = 1000 किग्रा।<br>चरण 2: 3.5 टन = 3.5 × 1000 = 3500 किग्रा।<br>अतः उत्तर = <b>3500</b>"},
    {"q":"5 क्विंटल चीनी से 250 ग्राम के कितने पैकेट बनेंगे?","o":["200","20000","500","2000"],"a":3,"e":"<b>हल:</b><br>चरण 1: 5 क्विंटल = 5 × 100 = 500 किग्रा = 500 × 1000 = 5,00,000 ग्राम।<br>चरण 2: पैकेट = 5,00,000 ÷ 250 = 2000।<br>अतः उत्तर = <b>2000</b><br><b>शॉर्टकट:</b> एक किग्रा में 250 ग्राम के 4 पैकेट ⇒ 500 × 4 = 2000।<br><b>ध्यान दें:</b> 200 तब आता है जब क्विंटल को 10 किग्रा मान लिया जाए।"},
    {"q":"1 किलोग्राम = ? मिलीग्राम","o":["10,00,000","1,00,000","10,000","1,000"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 किग्रा = 1000 ग्राम और 1 ग्राम = 1000 मिलीग्राम।<br>चरण 2: 1 किग्रा = 1000 × 1000 = 10,00,000 मिग्रा।<br>अतः उत्तर = <b>10,00,000</b>"},
    {"q":"1 वर्ग किलोमीटर = ? वर्ग मीटर","o":["1,000","10,00,000","1,00,000","10,000"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 किमी = 1000 मी।<br>चरण 2: 1 वर्ग किमी = 1000 × 1000 = 10,00,000 वर्ग मी।<br>अतः उत्तर = <b>10,00,000</b><br><b>ध्यान दें:</b> क्षेत्रफल में गुणक का वर्ग (1000²) लगता है, केवल 1000 नहीं।"},
    {"q":"1 एयर (are) = ? वर्ग मीटर","o":["10","1000","100","10000"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 एयर = 10 मी × 10 मी वाले वर्ग का क्षेत्रफल।<br>चरण 2: = 100 वर्ग मी।<br>अतः उत्तर = <b>100</b><br><b>शॉर्टकट:</b> 100 एयर = 1 हेक्टेयर = 10,000 वर्ग मी।"},
    {"q":"2 हेक्टेयर 35 एयर = ? वर्ग मीटर","o":["2350","235000","20350","23500"],"a":3,"e":"<b>हल:</b><br>चरण 1: 2 हेक्टेयर = 2 × 10,000 = 20,000 वर्ग मी।<br>चरण 2: 35 एयर = 35 × 100 = 3500 वर्ग मी।<br>चरण 3: कुल = 20,000 + 3,500 = 23,500 वर्ग मी।<br>अतः उत्तर = <b>23500</b><br><b>ध्यान दें:</b> 20350 तब आता है जब एयर को 10 वर्ग मी मान लिया जाए।"},
    {"q":"1 फुट में कितने इंच होते हैं?","o":["12","10","36","3"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 फुट = 12 इंच (मानक परिभाषा)।<br>अतः उत्तर = <b>12</b><br><b>ध्यान दें:</b> 36 इंच = 1 गज; 3 फुट = 1 गज।"},
    {"q":"1 गज = ? फुट","o":["12","3","36","2"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 गज = 3 फुट = 36 इंच।<br>अतः उत्तर = <b>3</b>"},
    {"q":"1 मील में कितने गज होते हैं?","o":["5280","1000","1760","1600"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 मील = 1760 गज = 5280 फुट।<br>अतः उत्तर = <b>1760</b><br><b>ध्यान दें:</b> 5280 फुट में है, गज में नहीं।"},
    {"q":"1 घन डेसीमीटर आयतन कितने लीटर के बराबर है?","o":["10","0.1","1000","1"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 लीटर की परिभाषा ही 1 घन डेसीमीटर है।<br>चरण 2: 1 घन डेसीमीटर = 10 × 10 × 10 = 1000 घन सेमी = 1000 मिली = 1 लीटर।<br>अतः उत्तर = <b>1</b>"},
    {"q":"1 मीटर लगभग कितने इंच के बराबर है?","o":["39.37","36","40.5","3.28"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 इंच = 2.54 सेमी।<br>चरण 2: 1 मी = 100 सेमी = 100 ÷ 2.54 ≈ 39.37 इंच।<br>अतः उत्तर = <b>39.37</b><br><b>ध्यान दें:</b> 36 इंच = 1 गज (मीटर से थोड़ा छोटा); 3.28 मीटर में फुट की संख्या है।"},
    {"q":"1 किलोमीटर लगभग कितने मील के बराबर है?","o":["1.609","0.621","0.5","0.75"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 मील ≈ 1.609 किमी।<br>चरण 2: 1 किमी = 1 ÷ 1.609 ≈ 0.621 मील।<br>अतः उत्तर = <b>0.621</b><br><b>ध्यान दें:</b> 1.609 उल्टा मान है।"},
    {"q":"घड़ी में सुबह 9:15 बजे हैं। 7 घंटे 50 मिनट बाद कितने बजेंगे?","o":["6:05 PM","5:15 PM","5:05 PM","4:55 PM"],"a":2,"e":"<b>हल:</b><br>चरण 1: सुबह 9:15 = 09:15 (24-घंटे में)।<br>चरण 2: 9:15 + 7 घंटे = 16:15।<br>चरण 3: 16:15 + 50 मिनट = 17:05।<br>चरण 4: 17:05 − 12 = 5:05 PM।<br>अतः उत्तर = <b>5:05 PM</b><br><b>शॉर्टकट:</b> 7 घंटे 50 मिनट = 8 घंटे − 10 मिनट ⇒ 9:15 + 8 घंटे = 17:15, फिर − 10 मिनट = 17:05।<br><b>ध्यान दें:</b> 15 + 50 = 65 मिनट = 1 घंटा 5 मिनट — इस हासिल को भूलने से 4:05/5:15 जैसे गलत उत्तर आते हैं।"},
    {"q":"1 जनवरी 2024 से 31 मार्च 2024 तक (दोनों दिन सहित) कुल कितने दिन हैं?","o":["90","92","89","91"],"a":3,"e":"<b>हल:</b><br>चरण 1: 2024 लीप वर्ष है (4 से विभाज्य), अतः फ़रवरी = 29 दिन।<br>चरण 2: जनवरी 31 + फ़रवरी 29 + मार्च 31।<br>चरण 3: कुल = 31 + 29 + 31 = 91 दिन।<br>अतः उत्तर = <b>91</b><br><b>ध्यान दें:</b> फ़रवरी 28 दिन मानने पर 90 आता है — लीप वर्ष जाँचें।"},
    {"q":"एक दशक में कितने महीने होते हैं?","o":["120","100","144","60"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 दशक = 10 वर्ष, 1 वर्ष = 12 महीने।<br>चरण 2: महीने = 10 × 12 = 120।<br>अतः उत्तर = <b>120</b>"},
    {"q":"1/4 दिन = ? मिनट","o":["240","360","480","300"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 दिन = 24 घंटे, अतः 1/4 दिन = 6 घंटे।<br>चरण 2: 6 घंटे = 6 × 60 = 360 मिनट।<br>अतः उत्तर = <b>360 मिनट</b><br><b>शॉर्टकट:</b> 1 दिन = 1440 मिनट; 1440 ÷ 4 = 360।"},
    {"q":"1 मीट्रिक टन = ? ग्राम","o":["10<sup>5</sup>","10<sup>7</sup>","10<sup>6</sup>","10<sup>9</sup>"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 टन = 1000 किग्रा = 10³ किग्रा।<br>चरण 2: 1 किग्रा = 10³ ग्राम।<br>चरण 3: 1 टन = 10³ × 10³ = 10⁶ ग्राम।<br>अतः उत्तर = <b>10⁶</b>"},
    {"q":"1 घन मीटर शुद्ध पानी (4°C) का द्रव्यमान लगभग कितना होता है?","o":["1 क्विंटल","100 किग्रा","10 टन","1 टन"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 घन मी = 1000 लीटर।<br>चरण 2: 4°C पर 1 लीटर शुद्ध पानी का द्रव्यमान = 1 किग्रा।<br>चरण 3: द्रव्यमान = 1000 किग्रा = 1 टन।<br>अतः उत्तर = <b>1 टन</b><br><b>ध्यान दें:</b> 1 क्विंटल और 100 किग्रा एक ही (गलत) मान हैं।"},
    {"q":"7 किग्रा 50 ग्राम को किलोग्राम में लिखें।","o":["7.05 किग्रा","7.5 किग्रा","7.005 किग्रा","70.5 किग्रा"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 ग्राम = 1/1000 किग्रा, अतः 50 ग्राम = 50/1000 = 0.050 किग्रा।<br>चरण 2: कुल = 7 + 0.050 = 7.05 किग्रा।<br>अतः उत्तर = <b>7.05 किग्रा</b><br><b>शॉर्टकट:</b> दशमलव के बाद तीन अंक ग्राम बताते हैं: 7.050।<br><b>ध्यान दें:</b> 7.5 किग्रा = 7 किग्रा 500 ग्राम होता है; 7.005 = 7 किग्रा 5 ग्राम।"},
    {"q":"3 मीटर 4 सेंटीमीटर को मीटर में लिखें।","o":["3.4 मी","3.04 मी","3.004 मी","30.4 मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 सेमी = 1/100 मी, अतः 4 सेमी = 0.04 मी।<br>चरण 2: कुल = 3 + 0.04 = 3.04 मी।<br>अतः उत्तर = <b>3.04 मी</b><br><b>ध्यान दें:</b> 3.4 मी = 3 मी 40 सेमी होगा — सेंटीमीटर के लिए दशमलव के बाद दो स्थान चाहिए।"},
    {"q":"4.5 हेक्टेयर = ? वर्ग मीटर","o":["4500","450000","45000","450"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 हेक्टेयर = 10,000 वर्ग मी।<br>चरण 2: 4.5 × 10,000 = 45,000 वर्ग मी।<br>अतः उत्तर = <b>45000</b>"},
    {"q":"1 वर्ग गज = ? वर्ग फुट","o":["3","12","144","9"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 गज = 3 फुट।<br>चरण 2: 1 वर्ग गज = 3 × 3 = 9 वर्ग फुट।<br>अतः उत्तर = <b>9</b><br><b>ध्यान दें:</b> 3 केवल लंबाई का गुणक है; 144 तो 1 वर्ग फुट में वर्ग इंच हैं।"},
    {"q":"1 समुद्री (नॉटिकल) मील = ? मीटर","o":["1852","1609","1760","1000"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 समुद्री मील = पृथ्वी पर देशांतर/अक्षांश के 1 मिनट (1′) की चाप-लंबाई।<br>चरण 2: अंतरराष्ट्रीय परिभाषा से 1 नॉटिकल मील = ठीक 1852 मी।<br>अतः उत्तर = <b>1852</b><br><b>ध्यान दें:</b> 1609 मी साधारण (स्थल) मील है; 1760 तो मील में गज की संख्या है।"},
    {"q":"\"प्रकाश वर्ष\" किस राशि का मात्रक है?","o":["समय","दूरी","चाल","द्रव्यमान"],"a":1,"e":"<b>हल:</b><br>चरण 1: प्रकाश वर्ष = प्रकाश द्वारा निर्वात में 1 वर्ष में तय की गई दूरी।<br>चरण 2: ≈ 9.46 × 10¹⁵ मी — अतः यह दूरी का मात्रक है।<br>अतः उत्तर = <b>दूरी</b><br><b>ध्यान दें:</b> नाम में \"वर्ष\" होने से इसे समय का मात्रक समझना आम गलती है।"},
    {"q":"18 घंटे, एक दिन का कौन-सा भाग है?","o":["2/3","1/2","3/4","4/5"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 दिन = 24 घंटे।<br>चरण 2: भाग = 18/24।<br>चरण 3: HCF 6 से सरल करें: 18/24 = 3/4।<br>अतः उत्तर = <b>3/4</b>"},
    {"q":"2.5 लीटर शरबत से 50 मिलीलीटर की कितनी शीशियाँ भरी जा सकती हैं?","o":["5","500","25","50"],"a":3,"e":"<b>हल:</b><br>चरण 1: 2.5 लीटर = 2.5 × 1000 = 2500 मिली।<br>चरण 2: शीशियाँ = 2500 ÷ 50 = 50।<br>अतः उत्तर = <b>50</b>"},
    {"q":"2 मिनट 30 सेकंड, 1 घंटे का कौन-सा भाग है?","o":["1/24","1/20","1/30","1/40"],"a":0,"e":"<b>हल:</b><br>चरण 1: 2 मिनट 30 सेकंड = 120 + 30 = 150 सेकंड।<br>चरण 2: 1 घंटा = 3600 सेकंड।<br>चरण 3: भाग = 150/3600 = 1/24।<br>अतः उत्तर = <b>1/24</b><br><b>शॉर्टकट:</b> मिनट में: 2.5/60 = 1/24।"},
    {"q":"6 मी × 4 मी × 3 मी माप वाले कमरे में कितने घन मीटर हवा है?","o":["62","72","84","70"],"a":1,"e":"<b>हल:</b><br>चरण 1: हवा का आयतन = कमरे का आयतन = ल × चौ × ऊँ।<br>चरण 2: = 6 × 4 × 3 = 72 घन मी।<br>अतः उत्तर = <b>72</b>"},
    {"q":"12 सेमी × 10 सेमी × 5 सेमी माप के डिब्बे की धारिता कितनी है?","o":["6 लीटर","60 लीटर","0.6 लीटर","0.06 लीटर"],"a":2,"e":"<b>हल:</b><br>चरण 1: आयतन = 12 × 10 × 5 = 600 घन सेमी।<br>चरण 2: 1 लीटर = 1000 घन सेमी, अतः 600 घन सेमी = 600/1000 = 0.6 लीटर।<br>अतः उत्तर = <b>0.6 लीटर</b><br><b>ध्यान दें:</b> 6 लीटर तब आता है जब 1 लीटर = 100 घन सेमी मान लिया जाए।"},
    {"q":"किसी किसान के पास 3 एकड़ भूमि है। यह लगभग कितने हेक्टेयर है?","o":["7.41","1.5","2.47","1.21"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 एकड़ ≈ 0.4047 हेक्टेयर (या 1 हेक्टेयर ≈ 2.47 एकड़)।<br>चरण 2: 3 एकड़ = 3 × 0.4047 ≈ 1.21 हेक्टेयर।<br>अतः उत्तर = <b>1.21</b><br><b>शॉर्टकट:</b> हेक्टेयर ≈ एकड़ ÷ 2.47 = 3 ÷ 2.47 ≈ 1.21।<br><b>ध्यान दें:</b> 7.41 तब आता है जब उल्टा 2.47 से गुणा कर दिया जाए।"},
    {"q":"घड़ी की मिनट की सुई 1 घंटे में कितने अंश घूमती है?","o":["360°","30°","180°","6°"],"a":0,"e":"<b>हल:</b><br>चरण 1: मिनट की सुई 60 मिनट (1 घंटे) में पूरा एक चक्कर लगाती है।<br>चरण 2: एक चक्कर = 360°।<br>अतः उत्तर = <b>360°</b><br><b>ध्यान दें:</b> 6° तो प्रति मिनट का मान है; 30° घंटे की सुई का प्रति घंटा मान है।"},
    {"q":"घड़ी की घंटे की सुई 1 मिनट में कितने अंश घूमती है?","o":["6°","0.5°","1°","30°"],"a":1,"e":"<b>हल:</b><br>चरण 1: घंटे की सुई 12 घंटे = 720 मिनट में 360° घूमती है।<br>चरण 2: प्रति मिनट = 360 ÷ 720 = 0.5°।<br>अतः उत्तर = <b>0.5°</b><br><b>शॉर्टकट:</b> घंटे की सुई 1 घंटे में 30° ⇒ 1 मिनट में 30/60 = ½°।<br><b>ध्यान दें:</b> 6° मिनट की सुई का प्रति मिनट मान है।"},
    {"q":"0.025 किलोमीटर = ? सेंटीमीटर","o":["250","25000","2500","25"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 किमी = 1000 मी = 1,00,000 सेमी।<br>चरण 2: 0.025 × 1,00,000 = 2500 सेमी।<br>अतः उत्तर = <b>2500</b><br><b>शॉर्टकट:</b> पहले मीटर: 0.025 किमी = 25 मी; फिर 25 × 100 = 2500 सेमी।"},
    {"q":"72 मी लंबे कपड़े से 1.2 मी के कितने टुकड़े काटे जा सकते हैं?","o":["6","600","72","60"],"a":3,"e":"<b>हल:</b><br>चरण 1: टुकड़ों की संख्या = कुल लंबाई ÷ एक टुकड़े की लंबाई।<br>चरण 2: 72 ÷ 1.2 = 720 ÷ 12 = 60।<br>अतः उत्तर = <b>60</b><br><b>ध्यान दें:</b> दशमलव हटाने के लिए अंश व हर दोनों को 10 से गुणा करें, अन्यथा 6 या 600 जैसी गलती होती है।"},
    {"q":"एक साधारण वर्ष (365 दिन) में कितने घंटे होते हैं?","o":["8760","8670","8640","8780"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 दिन = 24 घंटे।<br>चरण 2: 365 × 24 = 8760 घंटे।<br>अतः उत्तर = <b>8760</b><br><b>ध्यान दें:</b> 8640 = 360 × 24 है — 365 दिन लेने हैं।"},
    {"q":"5400 सेकंड = ?","o":["1 घंटा 40 मिनट","1 घंटा 30 मिनट","1 घंटा 50 मिनट","54 मिनट"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 घंटा = 3600 सेकंड; 5400 − 3600 = 1800 सेकंड शेष।<br>चरण 2: 1800 सेकंड = 1800 ÷ 60 = 30 मिनट।<br>अतः उत्तर = <b>1 घंटा 30 मिनट</b><br><b>शॉर्टकट:</b> 5400 ÷ 60 = 90 मिनट = 1 घंटा 30 मिनट।"},
    {"q":"मनुष्य के शरीर का सामान्य ताप 37°C है। फ़ारेनहाइट में यह कितना होगा?","o":["99.6°F","96.8°F","98.6°F","100°F"],"a":2,"e":"<b>हल:</b><br>चरण 1: सूत्र: F = (9/5) × C + 32।<br>चरण 2: F = (9/5) × 37 + 32 = 66.6 + 32।<br>चरण 3: = 98.6°F।<br>अतः उत्तर = <b>98.6°F</b><br><b>ध्यान दें:</b> 96.8 अंकों का उलट-फेर है।"},
    {"q":"किस ताप पर सेल्सियस और फ़ारेनहाइट पैमाने का पाठ्यांक समान होता है?","o":["0°","40°","100°","−40°"],"a":3,"e":"<b>हल:</b><br>चरण 1: मान लें दोनों पाठ्यांक = x, तो x = (9/5)x + 32।<br>चरण 2: x − (9/5)x = 32 ⇒ −(4/5)x = 32।<br>चरण 3: x = −40।<br>अतः उत्तर = <b>−40°</b><br><b>ध्यान दें:</b> 0° और 100° पर पाठ्यांक भिन्न होते हैं (32°F और 212°F)।"},
    {"q":"4 घंटे 25 मिनट 30 सेकंड = ? सेकंड","o":["15930","15330","16530","14930"],"a":0,"e":"<b>हल:</b><br>चरण 1: 4 घंटे = 4 × 3600 = 14,400 सेकंड।<br>चरण 2: 25 मिनट = 25 × 60 = 1,500 सेकंड।<br>चरण 3: कुल = 14,400 + 1,500 + 30 = 15,930 सेकंड।<br>अतः उत्तर = <b>15930</b>"},
    {"q":"3.6 क्विंटल चावल को 400 ग्राम के पैकेटों में भरने पर कितने पैकेट बनेंगे?","o":["90","900","9000","360"],"a":1,"e":"<b>हल:</b><br>चरण 1: 3.6 क्विंटल = 3.6 × 100 = 360 किग्रा = 3,60,000 ग्राम।<br>चरण 2: पैकेट = 3,60,000 ÷ 400 = 900।<br>अतः उत्तर = <b>900</b><br><b>शॉर्टकट:</b> 1 किग्रा में 400 ग्राम के 2.5 पैकेट ⇒ 360 × 2.5 = 900।<br><b>ध्यान दें:</b> 360 उत्तर तब आता है जब ग्राम में बदले बिना भाग दिया जाए।"},
    {"q":"5 घन मीटर = ? घन सेंटीमीटर","o":["5,00,000","50,000","50,00,000","5,000"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 घन मी = 10,00,000 घन सेमी।<br>चरण 2: 5 × 10,00,000 = 50,00,000 घन सेमी।<br>अतः उत्तर = <b>50,00,000</b>"},
    {"q":"निम्न में से कौन-सा वर्ष लीप वर्ष नहीं है?","o":["2000","2024","1600","1900"],"a":3,"e":"<b>हल:</b><br>चरण 1: नियम: सामान्य वर्ष 4 से विभाज्य हो तो लीप; शताब्दी वर्ष (00 वाले) तभी लीप जब 400 से विभाज्य हो।<br>चरण 2: 2000 ÷ 400 ✓ लीप; 1600 ÷ 400 ✓ लीप; 2024 ÷ 4 ✓ लीप।<br>चरण 3: 1900 ÷ 400 = 4.75 ✗ — अतः 1900 लीप वर्ष नहीं।<br>अतः उत्तर = <b>1900</b><br><b>ध्यान दें:</b> 1900 भी 4 से विभाज्य है, पर शताब्दी वर्ष होने से 400 वाला नियम लगता है।"},
    {"q":"SI पद्धति में द्रव्यमान की मूल इकाई क्या है?","o":["किलोग्राम","ग्राम","क्विंटल","पाउंड"],"a":0,"e":"<b>हल:</b><br>चरण 1: SI पद्धति की 7 मूल इकाइयों में द्रव्यमान की इकाई किलोग्राम (kg) है।<br>अतः उत्तर = <b>किलोग्राम</b><br><b>ध्यान दें:</b> ग्राम CGS पद्धति की इकाई है; पाउंड FPS की।"},
    {"q":"1 वर्ग सेंटीमीटर = ? वर्ग मिलीमीटर","o":["10","100","1000","0.01"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 सेमी = 10 मिमी।<br>चरण 2: 1 वर्ग सेमी = 10 × 10 = 100 वर्ग मिमी।<br>अतः उत्तर = <b>100</b>"},
    {"q":"एक खेत 500 मी लंबा व 300 मी चौड़ा है। धान बोने पर प्रति हेक्टेयर 40 क्विंटल उपज मिलती है। कुल उपज कितने टन है?","o":["600 टन","6 टन","60 टन","150 टन"],"a":2,"e":"<b>हल:</b><br>चरण 1: क्षेत्रफल = 500 × 300 = 1,50,000 वर्ग मी = 1,50,000 ÷ 10,000 = 15 हेक्टेयर।<br>चरण 2: उपज = 15 × 40 = 600 क्विंटल।<br>चरण 3: 10 क्विंटल = 1 टन ⇒ 600 ÷ 10 = 60 टन।<br>अतः उत्तर = <b>60 टन</b><br><b>ध्यान दें:</b> 600 टन तब आता है जब क्विंटल को टन में बदलना भूल जाएँ।"},
    {"q":"एक टंकी 1.2 मी × 80 सेमी × 50 सेमी की है। इसमें कितने लीटर पानी आएगा?","o":["4800 लीटर","48 लीटर","4.8 लीटर","480 लीटर"],"a":3,"e":"<b>हल:</b><br>चरण 1: सभी माप सेमी में: 120 सेमी × 80 सेमी × 50 सेमी।<br>चरण 2: आयतन = 120 × 80 × 50 = 4,80,000 घन सेमी।<br>चरण 3: लीटर = 4,80,000 ÷ 1000 = 480।<br>अतः उत्तर = <b>480 लीटर</b><br><b>शॉर्टकट:</b> मीटर में: 1.2 × 0.8 × 0.5 = 0.48 घन मी = 0.48 × 1000 = 480 लीटर।<br><b>ध्यान दें:</b> अलग-अलग इकाइयों को पहले एक इकाई में बदलें, अन्यथा 4800 या 48 जैसे गलत उत्तर आते हैं।"},
    {"q":"1 पाउंड लगभग कितने ग्राम के बराबर है?","o":["453.6","500","220","1000"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 पाउंड = 0.45359 किग्रा।<br>चरण 2: = 0.4536 × 1000 ≈ 453.6 ग्राम।<br>अतः उत्तर = <b>453.6</b><br><b>ध्यान दें:</b> 1 किग्रा ≈ 2.2 पाउंड — 220 उसी से भ्रम है।"},
    {"q":"1 एकड़ = ? डिसमिल","o":["10","100","40","1000"],"a":1,"e":"<b>हल:</b><br>चरण 1: डिसमिल (decimal) = एकड़ का सौवाँ भाग।<br>चरण 2: अतः 1 एकड़ = 100 डिसमिल (1 डिसमिल ≈ 435.6 वर्ग फुट)।<br>अतः उत्तर = <b>100</b>"},
    {"q":"यदि किसी दिन सूर्योदय सुबह 5:48 पर और सूर्यास्त शाम 6:27 पर हो, तो दिन की अवधि कितनी है?","o":["11 घंटे 39 मिनट","12 घंटे 21 मिनट","12 घंटे 39 मिनट","12 घंटे 49 मिनट"],"a":2,"e":"<b>हल:</b><br>चरण 1: सूर्योदय 5:48 और सूर्यास्त 6:27 PM = 18:27 (24-घंटे)।<br>चरण 2: 18:27 − 5:48: मिनट 27 − 48 नहीं घटता, अतः 1 घंटा उधार लें ⇒ 17 घंटे 87 मिनट − 5 घंटे 48 मिनट।<br>चरण 3: = 12 घंटे 39 मिनट।<br>अतः उत्तर = <b>12 घंटे 39 मिनट</b><br><b>शॉर्टकट:</b> 5:48 से 6:48 PM = 13 घंटे; 6:27 उससे 21 मिनट पहले ⇒ 13 घं − 21 मि = 12 घं 39 मि।<br><b>ध्यान दें:</b> 12 घंटे 21 मिनट वह गलती है जहाँ बड़े में से छोटा मिनट उलटा घटा दिया जाए।"},
    {"q":"1 कैरेट (रत्नों का भार) = ? मिलीग्राम","o":["100","20","2000","200"],"a":3,"e":"<b>हल:</b><br>चरण 1: रत्नों का मीट्रिक कैरेट = 0.2 ग्राम।<br>चरण 2: 0.2 × 1000 = 200 मिलीग्राम।<br>अतः उत्तर = <b>200</b><br><b>ध्यान दें:</b> सोने की शुद्धता वाला \"कैरेट\" (24 कैरेट) अलग अवधारणा है।"},
    {"q":"आयतन की SI इकाई क्या है?","o":["घन मीटर","लीटर","घन सेंटीमीटर","मिलीलीटर"],"a":0,"e":"<b>हल:</b><br>चरण 1: SI में लंबाई की इकाई मीटर है, अतः आयतन (लंबाई³) की इकाई घन मीटर (m³)।<br>अतः उत्तर = <b>घन मीटर</b><br><b>ध्यान दें:</b> लीटर प्रचलित इकाई है, SI इकाई नहीं।"},
    {"q":"0.4 घंटा = ? मिनट","o":["40","24","4","30"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 घंटा = 60 मिनट।<br>चरण 2: 0.4 × 60 = 24 मिनट।<br>अतः उत्तर = <b>24</b><br><b>ध्यान दें:</b> 0.4 घंटे को 40 मिनट समझना सबसे आम गलती है।"},
    {"q":"एक वर्गाकार भूखंड की भुजा 50 मी है। उसका क्षेत्रफल कितने एयर है?","o":["250","2.5","25","0.25"],"a":2,"e":"<b>हल:</b><br>चरण 1: क्षेत्रफल = भुजा² = 50 × 50 = 2500 वर्ग मी।<br>चरण 2: 1 एयर = 100 वर्ग मी।<br>चरण 3: एयर = 2500 ÷ 100 = 25।<br>अतः उत्तर = <b>25</b>"},
    {"q":"1 फुट = ? सेंटीमीटर","o":["25.4","12","33.3","30.48"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 फुट = 12 इंच और 1 इंच = 2.54 सेमी।<br>चरण 2: 1 फुट = 12 × 2.54 = 30.48 सेमी।<br>अतः उत्तर = <b>30.48</b>"},
    {"q":"एक बर्तन में 4 लीटर 250 मिली दूध था। उसमें से 1 लीटर 375 मिली निकाला गया और फिर 3 लीटर 650 मिली डाला गया। अब बर्तन में कितना दूध है?","o":["6 लीटर 525 मिली","6 लीटर 275 मिली","5 लीटर 525 मिली","7 लीटर 25 मिली"],"a":0,"e":"<b>हल:</b><br>चरण 1: सब मिली में: 4250 मिली दूध।<br>चरण 2: निकालने के बाद: 4250 − 1375 = 2875 मिली।<br>चरण 3: डालने के बाद: 2875 + 3650 = 6525 मिली = 6 लीटर 525 मिली।<br>अतः उत्तर = <b>6 लीटर 525 मिली</b><br><b>शॉर्टकट:</b> शुद्ध परिवर्तन = +3650 − 1375 = +2275 मिली ⇒ 4250 + 2275 = 6525।"},
    {"q":"एक कमरे का फ़र्श 6 मी × 4.5 मी है। इस पर 30 सेमी × 30 सेमी की कितनी टाइलें लगेंगी?","o":["30","270","300","3000"],"a":2,"e":"<b>हल:</b><br>चरण 1: फ़र्श का क्षेत्रफल = 600 सेमी × 450 सेमी = 2,70,000 वर्ग सेमी।<br>चरण 2: एक टाइल = 30 × 30 = 900 वर्ग सेमी।<br>चरण 3: टाइलें = 2,70,000 ÷ 900 = 300।<br>अतः उत्तर = <b>300</b><br><b>शॉर्टकट:</b> लंबाई में 600/30 = 20 टाइलें, चौड़ाई में 450/30 = 15 ⇒ 20 × 15 = 300।<br><b>ध्यान दें:</b> 270 वह गलती है जहाँ 27 वर्ग मी को 0.1 से भाग दिया जाए; टाइल 0.09 वर्ग मी की है।"},
    {"q":"1 हेक्टेयर भूमि में 25 मी × 20 मी के कितने भूखंड बनाए जा सकते हैं?","o":["40","20","50","200"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 हेक्टेयर = 10,000 वर्ग मी।<br>चरण 2: एक भूखंड = 25 × 20 = 500 वर्ग मी।<br>चरण 3: भूखंड = 10,000 ÷ 500 = 20।<br>अतः उत्तर = <b>20</b>"},
    {"q":"2.5 मी × 1.6 मी × 1.2 मी की खाली टंकी को 40 लीटर प्रति मिनट की दर से पानी देने वाला नल कितने समय में भर देगा?","o":["12 मिनट","1 घंटा 20 मिनट","1 घंटा 12 मिनट","2 घंटे"],"a":3,"e":"<b>हल:</b><br>चरण 1: टंकी का आयतन = 2.5 × 1.6 × 1.2 = 4.8 घन मी।<br>चरण 2: लीटर में = 4.8 × 1000 = 4800 लीटर।<br>चरण 3: समय = 4800 ÷ 40 = 120 मिनट = 2 घंटे।<br>अतः उत्तर = <b>2 घंटे</b><br><b>ध्यान दें:</b> 12 मिनट तब आता है जब घन मी को लीटर में बदलने में 1000 के बजाय 100 से गुणा हो।"},
    {"q":"किसी क्षेत्र में 1 मिमी वर्षा हुई। 1 हेक्टेयर भूमि पर गिरे पानी का आयतन कितना है?","o":["100 लीटर","1000 लीटर","10000 लीटर","1 लाख लीटर"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 हेक्टेयर = 10,000 वर्ग मी; वर्षा की ऊँचाई 1 मिमी = 0.001 मी।<br>चरण 2: आयतन = क्षेत्रफल × ऊँचाई = 10,000 × 0.001 = 10 घन मी।<br>चरण 3: 10 घन मी = 10 × 1000 = 10,000 लीटर।<br>अतः उत्तर = <b>10000 लीटर</b><br><b>शॉर्टकट:</b> 1 वर्ग मी पर 1 मिमी वर्षा = 1 लीटर ⇒ 10,000 वर्ग मी पर 10,000 लीटर।"},
    {"q":"चावल का भाव ₹42 प्रति किलोग्राम है। 2.4 क्विंटल चावल का मूल्य कितना होगा?","o":["₹10080","₹1008","₹100800","₹9800"],"a":0,"e":"<b>हल:</b><br>चरण 1: 2.4 क्विंटल = 2.4 × 100 = 240 किग्रा।<br>चरण 2: मूल्य = 240 × ₹42 = ₹10,080।<br>अतः उत्तर = <b>₹10080</b><br><b>ध्यान दें:</b> ₹1008 तब आता है जब क्विंटल को 10 किग्रा मान लिया जाए।"},
    {"q":"1 मी भुजा वाले एक खोखले घन में 10 सेमी भुजा वाले कितने घन रखे जा सकते हैं?","o":["10","100","10000","1000"],"a":3,"e":"<b>हल:</b><br>चरण 1: बड़े घन की भुजा = 1 मी = 100 सेमी।<br>चरण 2: प्रत्येक किनारे पर छोटे घन = 100 ÷ 10 = 10।<br>चरण 3: कुल घन = 10 × 10 × 10 = 1000।<br>अतः उत्तर = <b>1000</b><br><b>शॉर्टकट:</b> आयतन अनुपात: (100/10)³ = 10³ = 1000।<br><b>ध्यान दें:</b> 10 या 100 केवल एक किनारे/एक परत के घन हैं।"},
    {"q":"एक रेलगाड़ी रात 22:40 बजे चलकर अगले दिन सुबह 06:15 बजे गंतव्य पर पहुँचती है। यात्रा में कितना समय लगा?","o":["8 घंटे 25 मिनट","7 घंटे 35 मिनट","16 घंटे 25 मिनट","7 घंटे 25 मिनट"],"a":1,"e":"<b>हल:</b><br>चरण 1: 22:40 से आधी रात 24:00 तक = 1 घंटा 20 मिनट।<br>चरण 2: आधी रात से 06:15 तक = 6 घंटे 15 मिनट।<br>चरण 3: कुल = 1:20 + 6:15 = 7 घंटे 35 मिनट।<br>अतः उत्तर = <b>7 घंटे 35 मिनट</b><br><b>ध्यान दें:</b> सीधे 22:40 − 06:15 घटाने पर 16 घंटे 25 मिनट आता है — यह गलत है क्योंकि दिन बदल गया है।"},
    {"q":"5 किमी 40 मी का 3/4 भाग कितना है?","o":["3 किमी 30 मी","3 किमी 750 मी","3 किमी 780 मी","3 किमी 78 मी"],"a":2,"e":"<b>हल:</b><br>चरण 1: 5 किमी 40 मी = 5040 मी।<br>चरण 2: 3/4 भाग = 5040 × 3 ÷ 4 = 1260 × 3 = 3780 मी।<br>चरण 3: 3780 मी = 3 किमी 780 मी।<br>अतः उत्तर = <b>3 किमी 780 मी</b><br><b>ध्यान दें:</b> 5 किमी 40 मी को 5.4 किमी (5400 मी) पढ़ने पर गलत उत्तर आता है; 40 मी = 0.040 किमी।"},
    {"q":"3.6 मी लंबे धागे से 45 सेमी के कितने टुकड़े काटे जा सकते हैं?","o":["12","6","80","8"],"a":3,"e":"<b>हल:</b><br>चरण 1: 3.6 मी = 360 सेमी।<br>चरण 2: टुकड़े = 360 ÷ 45 = 8।<br>अतः उत्तर = <b>8</b><br><b>ध्यान दें:</b> इकाई बदले बिना 3.6 ÷ 45 जैसी गणना न करें।"},
    {"q":"लोहे का घनत्व 7.8 ग्राम प्रति घन सेमी है। 50 सेमी × 20 सेमी × 10 सेमी की लोहे की सिल्ली का द्रव्यमान कितना होगा?","o":["78 किग्रा","7.8 किग्रा","780 किग्रा","78 ग्राम"],"a":0,"e":"<b>हल:</b><br>चरण 1: आयतन = 50 × 20 × 10 = 10,000 घन सेमी।<br>चरण 2: द्रव्यमान = घनत्व × आयतन = 7.8 × 10,000 = 78,000 ग्राम।<br>चरण 3: 78,000 ग्राम = 78 किग्रा।<br>अतः उत्तर = <b>78 किग्रा</b>"},
    {"q":"1.5 किमी लंबी और 12 मी चौड़ी सड़क को ₹250 प्रति वर्ग मीटर की दर से पक्का करने का व्यय कितना होगा?","o":["₹4.5 लाख","₹45 लाख","₹4.5 करोड़","₹18 लाख"],"a":1,"e":"<b>हल:</b><br>चरण 1: लंबाई = 1.5 किमी = 1500 मी।<br>चरण 2: क्षेत्रफल = 1500 × 12 = 18,000 वर्ग मी।<br>चरण 3: व्यय = 18,000 × ₹250 = ₹45,00,000 = ₹45 लाख।<br>अतः उत्तर = <b>₹45 लाख</b><br><b>ध्यान दें:</b> किमी को मीटर में बदलना न भूलें; 1 लाख = 1,00,000।"},
    {"q":"एक घड़ी प्रतिदिन 3 मिनट तेज़ चलती है। इसे सोमवार दोपहर 12 बजे सही मिलाया गया। अगले सोमवार दोपहर 12 बजे यह कितना समय दिखाएगी?","o":["12:18","12:24","11:39","12:21"],"a":3,"e":"<b>हल:</b><br>चरण 1: सोमवार दोपहर से अगले सोमवार दोपहर तक = 7 दिन।<br>चरण 2: कुल तेज़ी = 7 × 3 = 21 मिनट।<br>चरण 3: घड़ी दिखाएगी = 12:00 + 21 मिनट = 12:21।<br>अतः उत्तर = <b>12:21</b><br><b>ध्यान दें:</b> तेज़ घड़ी आगे का समय दिखाती है, इसलिए 21 मिनट जोड़ें, घटाएँ नहीं (11:39 गलत)।"},
    {"q":"2 किग्रा 350 ग्राम × 6 = ?","o":["12 किग्रा 100 ग्राम","14 किग्रा 10 ग्राम","14 किग्रा 100 ग्राम","13 किग्रा 100 ग्राम"],"a":2,"e":"<b>हल:</b><br>चरण 1: 2 किग्रा 350 ग्राम = 2350 ग्राम।<br>चरण 2: 2350 × 6 = 14,100 ग्राम।<br>चरण 3: = 14 किग्रा 100 ग्राम।<br>अतः उत्तर = <b>14 किग्रा 100 ग्राम</b><br><b>ध्यान दें:</b> 350 × 6 = 2100 ग्राम = 2 किग्रा 100 ग्राम — यह 2 किग्रा हासिल जोड़ना न भूलें।"},
    {"q":"एक कार 1 लीटर पेट्रोल में 15 किमी चलती है। पेट्रोल ₹105 प्रति लीटर है। 360 किमी की यात्रा में पेट्रोल का व्यय कितना होगा?","o":["₹2250","₹2520","₹5400","₹2400"],"a":1,"e":"<b>हल:</b><br>चरण 1: आवश्यक पेट्रोल = 360 ÷ 15 = 24 लीटर।<br>चरण 2: व्यय = 24 × ₹105 = ₹2,520।<br>अतः उत्तर = <b>₹2520</b><br><b>ध्यान दें:</b> ₹2250 अंकों की अदला-बदली वाला भ्रम है।"},
    {"q":"एक आयताकार खेत का क्षेत्रफल 1.2 हेक्टेयर तथा लंबाई 150 मी है। उसकी चौड़ाई कितनी है?","o":["80 मी","8 मी","800 मी","120 मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1.2 हेक्टेयर = 1.2 × 10,000 = 12,000 वर्ग मी।<br>चरण 2: चौड़ाई = क्षेत्रफल ÷ लंबाई = 12,000 ÷ 150 = 80 मी।<br>अतः उत्तर = <b>80 मी</b>"},
    {"q":"4 हेक्टेयर क्षेत्रफल वाले वर्गाकार खेत के चारों ओर ₹30 प्रति मीटर की दर से बाड़ लगाने का व्यय कितना होगा?","o":["₹6000","₹12000","₹48000","₹24000"],"a":3,"e":"<b>हल:</b><br>चरण 1: 4 हेक्टेयर = 40,000 वर्ग मी।<br>चरण 2: वर्ग की भुजा = √40,000 = 200 मी।<br>चरण 3: परिमाप = 4 × 200 = 800 मी।<br>चरण 4: व्यय = 800 × ₹30 = ₹24,000।<br>अतः उत्तर = <b>₹24000</b><br><b>ध्यान दें:</b> ₹6000 तब आता है जब परिमाप के बजाय केवल एक भुजा (200 मी) ली जाए।"},
    {"q":"1.5 मी भुजा वाली एक घनाकार टंकी आधी पानी से भरी है। उसमें कितने लीटर पानी है?","o":["3375 लीटर","1125 लीटर","1687.5 लीटर","168.75 लीटर"],"a":2,"e":"<b>हल:</b><br>चरण 1: घन का आयतन = 1.5³ = 3.375 घन मी = 3375 लीटर।<br>चरण 2: आधा भरा ⇒ पानी = 3375 ÷ 2 = 1687.5 लीटर।<br>अतः उत्तर = <b>1687.5 लीटर</b><br><b>ध्यान दें:</b> 3375 पूरा आयतन है; \"आधी भरी\" शर्त न भूलें।"},
    {"q":"एक रोगी को 5 मिली दवा दिन में 3 बार, 10 दिन तक लेनी है। दवा 100 मिली की शीशी में आती है। कम से कम कितनी शीशियाँ खरीदनी होंगी?","o":["2","1","3","15"],"a":0,"e":"<b>हल:</b><br>चरण 1: प्रतिदिन दवा = 5 × 3 = 15 मिली।<br>चरण 2: 10 दिन में = 15 × 10 = 150 मिली।<br>चरण 3: शीशियाँ = 150 ÷ 100 = 1.5 ⇒ पूरी शीशियाँ ही खरीद सकते हैं, अतः 2।<br>अतः उत्तर = <b>2</b><br><b>ध्यान दें:</b> \"कम से कम\" में भिन्न को ऊपर पूर्णांक तक बढ़ाते हैं — 1 शीशी में दवा कम पड़ेगी।"},
    {"q":"0.0045 टन = ? ग्राम","o":["450","4500","45000","45"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 टन = 1000 किग्रा = 10,00,000 ग्राम।<br>चरण 2: 0.0045 × 10,00,000 = 4500 ग्राम।<br>अतः उत्तर = <b>4500</b><br><b>शॉर्टकट:</b> पहले किग्रा: 0.0045 × 1000 = 4.5 किग्रा = 4500 ग्राम।"},
    {"q":"एक गोली में 250 मिलीग्राम दवा होती है। 1.5 किग्रा दवा से ऐसी कितनी गोलियाँ बनेंगी?","o":["600","6000","60000","3750"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1.5 किग्रा = 1.5 × 10,00,000 = 15,00,000 मिग्रा।<br>चरण 2: गोलियाँ = 15,00,000 ÷ 250 = 6000।<br>अतः उत्तर = <b>6000</b><br><b>शॉर्टकट:</b> 1 ग्राम में 4 गोलियाँ ⇒ 1500 ग्राम में 1500 × 4 = 6000।"},
    {"q":"कागज़ के 500 पन्नों की एक रीम की मोटाई 5 सेमी है। एक पन्ने की मोटाई कितनी है?","o":["1 मिमी","0.01 मिमी","0.5 मिमी","0.1 मिमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: 5 सेमी = 50 मिमी।<br>चरण 2: एक पन्ना = 50 ÷ 500 = 0.1 मिमी।<br>अतः उत्तर = <b>0.1 मिमी</b>"},
    {"q":"10 मी लंबी, 30 सेमी मोटी और 2 मी ऊँची दीवार बनाने में 25 सेमी × 12.5 सेमी × 7.5 सेमी माप की कितनी ईंटें लगेंगी?","o":["2560","25600","256","2400"],"a":0,"e":"<b>हल:</b><br>चरण 1: दीवार का आयतन = 1000 सेमी × 30 सेमी × 200 सेमी = 60,00,000 घन सेमी।<br>चरण 2: एक ईंट = 25 × 12.5 × 7.5 = 2343.75 घन सेमी।<br>चरण 3: ईंटें = 60,00,000 ÷ 2343.75 = 2560।<br>अतः उत्तर = <b>2560</b><br><b>ध्यान दें:</b> दीवार के सभी माप सेमी में बदलें; मीटर और सेमी मिलाने से 256 या 25600 जैसी गलती होती है।"},
    {"q":"2 मी × 1.5 मी × 80 सेमी की टंकी पूरी पानी से भरी है। पानी का द्रव्यमान कितना है? (1 लीटर पानी = 1 किग्रा)","o":["240 किग्रा","24 टन","2.4 टन","2400 ग्राम"],"a":2,"e":"<b>हल:</b><br>चरण 1: आयतन = 2 × 1.5 × 0.8 = 2.4 घन मी (80 सेमी = 0.8 मी)।<br>चरण 2: 2.4 घन मी = 2400 लीटर = 2400 किग्रा।<br>चरण 3: 2400 किग्रा = 2.4 टन।<br>अतः उत्तर = <b>2.4 टन</b>"},
    {"q":"एक कार्यालय में काम सुबह 10:15 से शाम 5:45 तक होता है, जिसमें 45 मिनट का भोजनावकाश है। सप्ताह में 6 दिन काम होता है। सप्ताह में कुल कार्य-समय कितना है?","o":["45 घंटे","36 घंटे","40 घंटे 50 मिनट","40 घंटे 30 मिनट"],"a":3,"e":"<b>हल:</b><br>चरण 1: 10:15 से 17:45 तक = 7 घंटे 30 मिनट।<br>चरण 2: भोजनावकाश घटाएँ: 7:30 − 0:45 = 6 घंटे 45 मिनट प्रतिदिन।<br>चरण 3: सप्ताह में = 6.75 × 6 = 40.5 घंटे = 40 घंटे 30 मिनट।<br>अतः उत्तर = <b>40 घंटे 30 मिनट</b><br><b>ध्यान दें:</b> 45 घंटे तब आता है जब भोजनावकाश घटाना भूल जाएँ।"},
    {"q":"2.25 घंटे = ? सेकंड","o":["13500","8100","2250","9000"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 घंटा = 3600 सेकंड।<br>चरण 2: 2.25 × 3600 = 8100 सेकंड।<br>अतः उत्तर = <b>8100</b><br><b>शॉर्टकट:</b> 2.25 घंटे = 2 घंटे 15 मिनट = 7200 + 900 = 8100 सेकंड।"},
    {"q":"एक साधारण वर्ष (365 दिन) में कुल कितने मिनट होते हैं?","o":["525600","52560","8760","31536000"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 दिन = 24 × 60 = 1440 मिनट।<br>चरण 2: 365 × 1440 = 5,25,600 मिनट।<br>अतः उत्तर = <b>525600</b><br><b>ध्यान दें:</b> 8760 घंटे हैं; 31536000 सेकंड हैं।"},
    {"q":"60 मी × 40 मी के आयताकार बगीचे के अंदर चारों ओर 2.5 मी चौड़ा रास्ता है। रास्ते का क्षेत्रफल कितना है?","o":["400 वर्ग मी","500 वर्ग मी","475 वर्ग मी","1925 वर्ग मी"],"a":2,"e":"<b>हल:</b><br>चरण 1: रास्ता अंदर की ओर है, अतः भीतरी भाग = (60 − 2×2.5) × (40 − 2×2.5) = 55 × 35 = 1925 वर्ग मी।<br>चरण 2: बगीचे का कुल क्षेत्रफल = 60 × 40 = 2400 वर्ग मी।<br>चरण 3: रास्ते का क्षेत्रफल = 2400 − 1925 = 475 वर्ग मी।<br>अतः उत्तर = <b>475 वर्ग मी</b><br><b>शॉर्टकट:</b> अंदर के रास्ते का सूत्र: 2w(l + b − 2w) = 2 × 2.5 × (60 + 40 − 5) = 5 × 95 = 475।<br><b>ध्यान दें:</b> 500 (= 2w(l+b)) में कोनों के 4 वर्ग दो बार गिने जाते हैं; 1925 भीतरी भाग है।"},
    {"q":"पानी के एक टैंकर की धारिता 12 किलोलीटर है। इससे 20 लीटर के कितने कैन भरे जा सकते हैं?","o":["60","600","6000","240"],"a":1,"e":"<b>हल:</b><br>चरण 1: 12 किलोलीटर = 12 × 1000 = 12,000 लीटर।<br>चरण 2: कैन = 12,000 ÷ 20 = 600।<br>अतः उत्तर = <b>600</b>"},
    {"q":"एक ट्रक में 8 टन अनाज लदा है। 50 किग्रा की कितनी बोरियाँ हैं?","o":["16","1600","80","160"],"a":3,"e":"<b>हल:</b><br>चरण 1: 8 टन = 8 × 1000 = 8000 किग्रा।<br>चरण 2: बोरियाँ = 8000 ÷ 50 = 160।<br>अतः उत्तर = <b>160</b><br><b>ध्यान दें:</b> 1600 तब आता है जब टन = 10,000 किग्रा मान लिया जाए।"},
    {"q":"750 ग्राम और 2 किग्रा का अनुपात क्या है?","o":["3 : 8","75 : 2","8 : 3","3 : 4"],"a":0,"e":"<b>हल:</b><br>चरण 1: दोनों को एक इकाई में: 2 किग्रा = 2000 ग्राम।<br>चरण 2: अनुपात = 750 : 2000।<br>चरण 3: HCF 250 से भाग: 3 : 8।<br>अतः उत्तर = <b>3 : 8</b><br><b>ध्यान दें:</b> 75 : 2 इकाई बदले बिना लिखा गया अनुपात है।"},
    {"q":"45 मिनट, 2 घंटे का कितना प्रतिशत है?","o":["45%","22.5%","37.5%","40%"],"a":2,"e":"<b>हल:</b><br>चरण 1: 2 घंटे = 120 मिनट।<br>चरण 2: प्रतिशत = (45 ÷ 120) × 100 = 37.5%।<br>अतः उत्तर = <b>37.5%</b><br><b>ध्यान दें:</b> 45% तब आता है जब 2 घंटे = 100 मिनट मान लें।"},
    {"q":"2.5 एकड़ भूमि में 40-40 डिसमिल के अधिकतम कितने पूरे प्लॉट काटे जा सकते हैं? (1 एकड़ = 100 डिसमिल)","o":["625","62","7","6"],"a":3,"e":"<b>हल:</b><br>चरण 1: 2.5 एकड़ = 2.5 × 100 = 250 डिसमिल।<br>चरण 2: प्लॉट = 250 ÷ 40 = 6.25।<br>चरण 3: केवल पूरे प्लॉट गिनें ⇒ 6 (शेष 10 डिसमिल बचेगी)।<br>अतः उत्तर = <b>6</b><br><b>ध्यान दें:</b> \"अधिकतम पूरे\" में भिन्न को नीचे पूर्णांक तक काटते हैं, 7 नहीं।"},
    {"q":"1 किमी रेलमार्ग बिछाने के लिए 12.5 मी लंबी पटरियाँ प्रयोग होती हैं। मार्ग में दो समानांतर पटरियाँ होती हैं। कुल कितनी पटरियाँ लगेंगी?","o":["160","80","40","320"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 किमी = 1000 मी; एक लाइन में पटरियाँ = 1000 ÷ 12.5 = 80।<br>चरण 2: दो समानांतर लाइनें ⇒ 80 × 2 = 160।<br>अतः उत्तर = <b>160</b><br><b>ध्यान दें:</b> 80 केवल एक लाइन की पटरियाँ हैं।"},
    {"q":"एक पाइप से प्रति सेकंड 2 लीटर पानी निकलता है। 1 घंटे में कितना पानी निकलेगा?","o":["72 घन मी","7.2 घन मी","0.72 घन मी","120 घन मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 घंटा = 3600 सेकंड।<br>चरण 2: पानी = 2 × 3600 = 7200 लीटर।<br>चरण 3: 1000 लीटर = 1 घन मी ⇒ 7200 ÷ 1000 = 7.2 घन मी।<br>अतः उत्तर = <b>7.2 घन मी</b>"},
    {"q":"किसी वस्तु का तापमान 10°C बढ़ाया गया। फ़ारेनहाइट पैमाने पर यह वृद्धि कितनी होगी?","o":["50°F","10°F","18°F","28°F"],"a":2,"e":"<b>हल:</b><br>चरण 1: तापमान के अंतर (वृद्धि) में केवल पैमाने का गुणक लगता है: ΔF = (9/5) × ΔC।<br>चरण 2: ΔF = (9/5) × 10 = 18°F।<br>अतः उत्तर = <b>18°F</b><br><b>ध्यान दें:</b> अंतर में +32 नहीं जुड़ता; +32 जोड़ने पर 50°F (गलत) आता है।"},
    {"q":"1 मिलीमीटर = ? माइक्रोमीटर","o":["10","100","10⁶","1000"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 मिमी = 10⁻³ मी और 1 माइक्रोमीटर = 10⁻⁶ मी।<br>चरण 2: 1 मिमी ÷ 1 µm = 10⁻³ ÷ 10⁻⁶ = 10³ = 1000।<br>अतः उत्तर = <b>1000</b>"}
  ]
});
